
/* ===== 桌宠逻辑（从 HTML 版拆分） ===== */
/* ================= 工具 ================= */
const $=s=>document.querySelector(s);

/* ================= Tauri 桌面环境 ================= */
const IS_TAURI=!!(window.__TAURI__&&window.__TAURI__.core);
const T=window.__TAURI__||{};
function invoke(cmd,args){return IS_TAURI?T.core.invoke(cmd,args||{}):Promise.reject(new Error('此功能需要桌面应用版'))}
function toAsset(p){return IS_TAURI?T.core.convertFileSrc(p):p}
async function saveBytes(dataB64,defaultName,filterName,filterExt){
  if(!IS_TAURI)return false;
  const ok=await invoke('save_bytes',{data:dataB64,defaultName,filterName,filterExt});
  if(ok===false)toast('已取消保存');
  return ok===true;
}
function blobToB64(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(blob)})}
const fmt=n=>String(n).padStart(2,'0');
function ts(){const d=new Date();return d.getFullYear()+'-'+fmt(d.getMonth()+1)+'-'+fmt(d.getDate())+'_'+fmt(d.getHours())+fmt(d.getMinutes())}
async function download(blob,name){
  if(IS_TAURI){
    const b64=await blobToB64(blob);
    const ext=(name.split('.').pop()||'bin').toLowerCase();
    const filter={png:['图片','png'],jpg:['图片','jpg'],jpeg:['图片','jpeg'],webp:['图片','webp'],gif:['GIF','gif'],pdf:['PDF','pdf'],zip:['ZIP','zip'],webm:['视频','webm'],bat:['脚本','bat'],command:['脚本','command'],txt:['文本','txt']}[ext]||['文件',ext];
    return saveBytes(b64,name,filter[0],filter[1]);
  }
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},6000);
}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;$('#toast').appendChild(t);setTimeout(()=>t.remove(),3600)}
function humanSize(n){if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(2)+' MB'}
function loadLib(url,globalName){return new Promise((res,rej)=>{if(window[globalName])return res(window[globalName]);const s=document.createElement('script');s.src=url;s.onload=()=>res(window[globalName]);s.onerror=()=>rej(new Error('库加载失败: '+url));document.head.appendChild(s)})}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

/* ================= 音效 ================= */
let AC=null;
const settings={name:'三虎',size:172,speed:1,sound:true};
function beep(f,d,type='triangle',g=0.045,when=0){
  if(!settings.sound)return;
  try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();
    const t=AC.currentTime+when,o=AC.createOscillator(),v=AC.createGain();
    o.type=type;o.frequency.setValueAtTime(f,t);
    v.gain.setValueAtTime(0.0001,t);v.gain.exponentialRampToValueAtTime(g,t+0.012);v.gain.exponentialRampToValueAtTime(0.0001,t+d);
    o.connect(v).connect(AC.destination);o.start(t);o.stop(t+d+0.06);
  }catch(e){}
}
function sfxMeow(){beep(520,0.10,'triangle',0.05);beep(780,0.09,'triangle',0.045,0.10);beep(430,0.16,'triangle',0.05,0.19)}
function sfxTap(){beep(880,0.05,'square',0.03)}
function sfxAlert(){beep(660,0.14,'square',0.04);beep(880,0.2,'square',0.04,0.16)}

/* ================= 精灵 ================= */
const SPRITE_DATA={
  idle:['','','','','',''],
  walk:['','','','','',''],
  happy:['','','','','',''],
  rain:['','','','','',''],
  jump:['','','','','',''],
};
const imgs={};
function loadSprites(){
  const jobs=[];
  Object.keys(SPRITE_DATA).forEach(st=>{
    imgs[st]=[];
    SPRITE_DATA[st].forEach((b64,idx)=>jobs.push(new Promise((res,rej)=>{const i=new Image();i.onload=()=>{imgs[st][idx]=i;res()};i.onerror=rej;i.src='data:image/png;base64,'+b64})));
  });
  return Promise.all(jobs);
}

/* ================= 桌宠引擎 ================= */
const canvas=$('#pet'),ctx=canvas.getContext('2d');
let W=0,H=0,DPR=1;
function resize(){DPR=window.devicePixelRatio||1;W=window.innerWidth;H=window.innerHeight;canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}
window.addEventListener('resize',resize);

const pet={x:0,groundY:0,vx:0,state:'idle',frame:0,ft:0,bob:0,lean:0,facing:1,hop:0,drag:false,dragDX:0,t:0,sleepT:0,lastTap:0,rainT:0,jumpT:0};
let mouse={x:0,y:0};
let bubbleTimer=null,bubbleQ=[];
function bubble(text,ms=3200){
  bubbleQ.push([text,ms]);
  if(bubbleTimer)return;
  const pop=()=>{if(!bubbleQ.length){bubbleTimer=null;return}
    const [t,m]=bubbleQ.shift();$('#bubbleText').textContent=t;
    const b=$('#bubble');b.classList.add('show');positionBubble();
    bubbleTimer=setTimeout(()=>{b.classList.remove('show');bubbleTimer=null;pop()},m)};
  pop();
}
function positionBubble(){
  const b=$('#bubble');
  const bw=b.offsetWidth||120;
  let bx=Math.max(30,Math.min(W-30,pet.x));
  if(bx<bw/2+30)bx=bw/2+30;
  if(bx>W-bw/2-30)bx=W-bw/2-30;
  b.style.left=bx+'px';
  b.style.bottom=(H-pet.groundY+150)+'px';
}
const GREETINGS=['你好呀，我是{name}~','今天也要加油哦！','想我了吗~','喵呜~','别盯着我看啦！','陪我玩嘛！','咕噜咕噜…','盯——'];
function randLine(arr){return arr[Math.floor(Math.random()*arr.length)]}

function openDock(){
  const d=$('#dock');d.classList.add('show');
  clearTimeout(openDock._t);openDock._t=setTimeout(()=>d.classList.remove('show'),7000);
}
function closeDock(){$('#dock').classList.remove('show')}

/* 待机帧切换（atlas 完整动画：按状态在帧序列中循环） */
const FRAME_MS={idle:140,walk:110,happy:120,rain:160,jump:100};
function tickFrame(dt){
  pet.ft+=dt;
  const ms=FRAME_MS[pet.state]||140;
  const n=imgs[pet.state]?imgs[pet.state].length:1;
  const interval=ms/1000/settings.speed;
  if(pet.ft>=interval){pet.ft=0;pet.frame=(pet.frame+1)%n}
}

/* 行走 */
function startWalk(){
  pet.state='walk';pet.walkT=6;
  const margin=80;
  const target=mouse.x>W/2?margin+Math.random()*120:W-margin-Math.random()*120;
  pet.targetX=Math.max(margin,Math.min(W-margin,target));
  pet.facing=pet.targetX>pet.x?1:-1;
  pet.hop=1;sfxTap();
}
function walkUpdate(dt){
  const spd=140*settings.speed*dt;
  const dx=pet.targetX-pet.x;
  if(Math.abs(dx)<4){pet.x=pet.targetX;pet.state='idle';pet.facing=pet.targetX>W/2?1:-1;return}
  pet.facing=dx>0?1:-1;
  pet.x+=Math.sign(dx)*Math.min(spd,Math.abs(dx));
  pet.bob=Math.abs(Math.sin(pet.t*10))*3;
}

/* 状态机更新 */
function petUpdate(dt){
  pet.t+=dt*settings.speed;
  if(pet.state==='idle'){
    pet.bob=Math.sin(pet.t*2.2)*2.5*settings.speed;
    tickFrame(dt);
    pet.sleepT+=dt;
    if(pet.sleepT>75&&Math.random()<0.003){bubble('zZ…',1500)}
  }else if(pet.state==='happy'){
    pet.hop=Math.max(0,pet.hop-dt*2.4);
    tickFrame(dt);
  }else if(pet.state==='walk'){
    tickFrame(dt);
    walkUpdate(dt);
  }else if(pet.state==='jump'){
    tickFrame(dt);
    pet.jumpT-=dt;
    pet.bob=Math.sin(pet.t*7)*1.5;
    if(pet.jumpT<=0)pet.state='idle';
  }else if(pet.state==='rain'){
    tickFrame(dt);
    pet.rainT-=dt;
    pet.bob=Math.sin(pet.t*9)*1.2;
    if(pet.rainT<=0)pet.state='idle';
  }
  pet.lean=Math.max(-0.10,Math.min(0.10,(mouse.x-pet.x)/W*0.5));
}

const SPRITE_W=160,SPRITE_H=160;
/* 渲染 */
function render(){
  ctx.clearRect(0,0,W,H);
  drawFloor();
  const frames=imgs[pet.state]||imgs.idle;
  const img=frames[pet.frame%frames.length]||frames[0];
  const scale=(pet.state==='rain'?settings.size*0.92:settings.size)/SPRITE_H;
  const g=pet.groundY;
  let bx=pet.x,by=g+pet.bob*scale*0.5+(pet.state==='happy'?pet.hop*18:0);
  const rot=pet.state==='happy'?Math.sin(pet.t*6)*0.02:0;
  ctx.save();
  ctx.translate(bx,by);
  ctx.scale(pet.facing*scale,scale);
  ctx.rotate(rot+pet.lean*0.6);
  ctx.imageSmoothingEnabled=false;
  ctx.drawImage(img,-SPRITE_W/2,-SPRITE_H*0.9,SPRITE_W,SPRITE_H);
  ctx.restore();
  if(pet.state==='rain')drawRain();
  if(pet.state==='happy'&&pet.hop>0.5){const r=Math.sin(pet.t*18)*0.3;ctx.strokeStyle='rgba(239,231,214,.25)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(pet.x-18,by-150);ctx.quadraticCurveTo(pet.x-18-r*8,by-165,pet.x-18+r*10,by-150);ctx.stroke()}
}

function drawFloor(){
  ctx.fillStyle='rgba(239,231,214,.14)';
  const y=H-3;
  const n=Math.ceil(W/12);
  for(let i=0;i<n;i++){if((i*12+pet.t*8*settings.speed)%24<12)ctx.fillRect(i*12-(pet.t*8*settings.speed)%12,y,10,2)}
}
let rainDrops=[];
function drawRain(){
  if(!rainDrops.length){for(let i=0;i<60;i++)rainDrops.push({x:Math.random()*W,y:Math.random()*H,s:1+Math.random()*1.6})}
  ctx.fillStyle='rgba(140,180,230,.5)';
  for(const d of rainDrops){
    d.y+=14*d.s;d.x-=0.8*d.s;
    if(d.y>H){d.y=-10;d.x=Math.random()*W}
    ctx.fillRect(d.x,d.y,1.5,7*d.s);
  }
  ctx.fillStyle='rgba(10,14,26,.18)';ctx.fillRect(0,0,W,H);
}

/* 天气预警: 下雨动画 */
let rainCooldown=0;
function triggerRainAlert(){
  if(Date.now()<rainCooldown||pet.state==='rain')return;
  rainCooldown=Date.now()+4*3600*1000;
  pet.state='rain';pet.rainT=10;rainDrops=[];
  bubble('要下雨啦，记得带伞哦~',4200);
  sfxAlert();
}
function resetRain(){pet.state='idle'}

/* 循环 */
let lastT=performance.now();
function loop(now){
  const dt=Math.min(0.05,(now-lastT)/1000);lastT=now;
  petUpdate(dt);render();
  requestAnimationFrame(loop);
}

/* ================= 交互 ================= */
let downPos=null,dragOn=false,moved=false;
function petHit(mx,my){
  const half=pet.state==='happy'?settings.size*0.75:settings.size*0.5;
  return Math.abs(mx-pet.x)<half*0.95&&my>pet.groundY-settings.size*1.25&&my<pet.groundY+10;
}
canvas.addEventListener('pointerdown',e=>{
  e.preventDefault();
  const mx=e.clientX,my=e.clientY;
  if(!petHit(mx,my)){closeDock();return}
  downPos={x:mx,y:my};moved=false;movedJiggle=false;dragOn=true;
  canvas.setPointerCapture(e.pointerId);
  canvas.classList.add('grabbing');
  AC&&AC.resume&&AC.resume();
});
canvas.addEventListener('pointermove',e=>{
  mouse.x=e.clientX;mouse.y=e.clientY;
  if(!dragOn||!downPos)return;
  const dx=e.clientX-downPos.x,dy=e.clientY-downPos.y;
  if(Math.abs(dx)+Math.abs(dy)>6)moved=true;
  if(moved){
    pet.x=Math.max(50,Math.min(W-50,e.clientX));
    if(pet.state==='idle'||pet.state==='walk')pet.state='idle';
    pet.bob=Math.sin(pet.t*6)*1;
    movedJiggle=true;
  }
});
function onUp(e){
  if(!dragOn)return;
  dragOn=false;canvas.classList.remove('grabbing');
  if(moved&&movedJiggle){movedJiggle=false;pet.state='jump';pet.jumpT=0.9;pet.frame=0;pet.ft=0;downPos=null;return}
  if(!moved&&downPos){
    const now=Date.now();
    if(now-pet.lastTap<320){startWalk();pet.lastTap=0;return}
    pet.lastTap=now;
    pet.state='happy';pet.hop=1;pet.sleepT=0;
    sfxMeow();
    bubble(randLine(GREETINGS).replace('{name}',settings.name));
    openDock();
  }
  downPos=null;
}
canvas.addEventListener('pointerup',onUp);
canvas.addEventListener('pointercancel',onUp);
canvas.addEventListener('dblclick',e=>{e.preventDefault();startWalk()});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();openDock()});
canvas.addEventListener('pointerleave',()=>{mouse.x=W/2});
window.addEventListener('resize',()=>{pet.x=Math.max(50,Math.min(W-50,pet.x));});

/* ================= 工具栏 ================= */
const DOCK_ITEMS=[
  ['capture','截图 / 录屏'],['files','格式转换'],['zip','压缩 / 解压'],['timer','定时任务'],['todo','待办'],['weather','天气'],['settings','设置'],['about','说明']
];
function buildDock(){
  const d=$('#dock');d.innerHTML='';
  DOCK_ITEMS.forEach(([id,label])=>{
    const b=document.createElement('button');
    b.textContent=label;
    b.onclick=()=>{sfxTap();closeDock();openPanel(id)};
    d.appendChild(b);
  });
}

/* ================= 初始化 ================= */
function init(){
  resize();
  pet.x=W/2;pet.groundY=H-8;
  $('#petName').textContent=settings.name;
  $('#netState').textContent=navigator.onLine?'':'离线';
  buildDock();
  loadSprites().then(()=>{requestAnimationFrame(loop)});
  loadSettings();
  restoreTimers();
  restoreTodos();
  if(savedCity())fetchWeather(savedCity(),true);
  setInterval(checkTimers,6000);
  if(IS_TAURI){
    // 拖拽条：移动窗口 / 隐藏到托盘
    const tb=$('#topbar');tb.hidden=false;
    const win=T.window.getCurrentWindow();
    tb.addEventListener('pointerdown',e=>{
      if(e.target.id==='tbHide')return;
      win.startDragging().catch(()=>{});
    });
    $('#tbHide').onclick=()=>{win.hide();toast('已隐藏到托盘（左键点托盘图标找回）')};
    // 托盘菜单打开设置
    T.event.listen('open-panel',e=>openPanel(e.payload));
    // 窗口选择高亮
    T.event.listen('picker-window',e=>{
      pickerWin=e.payload;
      if(pickerActive)renderPickerWin(pickerWin);
    });
    // 全局文件拖拽（桌面版）
    try{
      T.webview.getCurrentWebview().onDragDropEvent(e=>{
        try{e.preventDefault&&e.preventDefault()}catch(_){}
        const p=e.payload;
        if(p&&p.type==='drop')handleExternalDrop(p.paths||[]);
      });
    }catch(err){console.warn('拖拽监听失败',err)}
  }
}
window.addEventListener('DOMContentLoaded',init);
/* ================= 弹窗系统 ================= */
const PANELS={};
function openPanel(id){
  const m=$('#modal');
  m.innerHTML=PANELS[id]();
  m.classList.add('show');
  bindPanel(id);
  const close=()=>m.classList.remove('show');
  m.querySelector('.close').onclick=close;
  m.addEventListener('pointerdown',e=>{if(e.target===m)close()});
}
function bindPanel(id){
  const map={
    capture:bindCapture,files:bindFiles,zip:bindZip,timer:bindTimer,
    todo:bindTodo,weather:bindWeather,settings:bindSettings,about:()=>{}
  };
  map[id]&&map[id]();
}
function head(title){return `<div class="panel-head"><h2>${title}</h2><button class="close">✕</button></div>`}

/* ================= 截图 / 录屏 ================= */
let pickerActive=false,pickerWin=null;
let rec=null,recChunks=[],recStream=null;
PANELS.capture=()=>`
${head('截图 / 录屏')}
<div class="panel-body">
  <p class="note">${IS_TAURI?'桌面应用版：<b>截图</b>直接截全屏；<b>窗口选择</b>进入选择模式，鼠标移到目标窗口会出现红色选框，再点「截这个窗口 / 录这个窗口」。录屏输出 GIF。':'浏览器版：使用系统屏幕选择器，<b>全屏</b>选「整个屏幕」；<b>窗口</b>选「窗口」标签页，鼠标移到哪个窗口即出现高亮选框。需要 Chrome / Edge。'}</p>
  <div class="row">
    <button class="btn primary" id="capShot">截图</button>
    <button class="btn" id="capWin">窗口选择</button>
    <button class="btn" id="capStart">录屏</button>
    <button class="btn danger" id="capStop" disabled>停止</button>
  </div>
  <div id="pickerBox"></div>
  <div id="capStatus" class="note">状态：空闲</div>
</div>`;
function renderPickerWin(w){
  const box=$('#pickerBox');
  if(!box)return;
  if(!pickerActive||!w){box.innerHTML='';return}
  box.innerHTML=`<div class="pickwin">当前指向：<b>${escapeHtml(w.title)}</b>
    <div class="row">
      <button class="btn primary" id="pwShot">截这个窗口</button>
      <button class="btn" id="pwRec">录这个窗口</button>
    </div></div>`;
  const set=(t,c)=>{const s=$('#capStatus');if(s)s.innerHTML=`状态：<span class="${c||''}">${t}</span>`};
  $('#pwShot').onclick=async()=>{
    set('正在截取窗口…');
    try{const ok=await invoke('screenshot_window',{windowId:w.id});set(ok?'已保存截图':'已取消','ok')}catch(e){set('截图失败：'+e.message,'err')}
  };
  $('#pwRec').onclick=async()=>{
    const secs=Math.min(60,Math.max(2,parseInt(prompt('录制几秒（2-60）？','8')||'8',10)));
    const fps=Math.min(10,Math.max(2,parseInt(prompt('帧率（2-10）？','8')||'8',10)));
    set(`正在录制「${w.title}」 ${secs} 秒…（完成后弹保存框）`,'warnc');
    try{const ok=await invoke('record_gif',{mode:'window',windowId:w.id,seconds:secs,fps});set(ok?'已保存 GIF':'已取消','ok')}catch(e){set('录制失败：'+e.message,'err')}
  };
}
function bindCapture(){
  const st=$('#capStatus');
  const set=(t,c)=>st.innerHTML=`状态：<span class="${c||''}">${t}</span>`;
  $('#capShot').onclick=async()=>{
    if(IS_TAURI){
      set('正在截取全屏…');
      try{const ok=await invoke('screenshot_full');set(ok?'已保存截图':'已取消','ok')}catch(e){set('截图失败：'+e.message,'err')}
      return;
    }
    try{
      const s=await navigator.mediaDevices.getDisplayMedia({video:{cursor:'always'},audio:false});
      const v=document.createElement('video');v.srcObject=s;v.muted=true;await v.play();
      await sleep(350);
      const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;
      c.getContext('2d').drawImage(v,0,0);
      s.getTracks().forEach(t=>t.stop());
      c.toBlob(b=>{download(b,'截图-'+ts()+'.png');set('已保存截图','ok')},'image/png');
    }catch(e){set('已取消或失败：'+e.message,'err')}
  };
  $('#capWin').onclick=async()=>{
    if(!IS_TAURI){set('窗口选择请在桌面应用版中使用','err');return}
    pickerActive=!pickerActive;
    const btn=$('#capWin');
    if(pickerActive){
      await invoke('start_picker');
      set('窗口选择中：移动鼠标到目标窗口，出现红色选框后点下方按钮','warnc');
      btn.textContent='取消选择';
      renderPickerWin(pickerWin);
    }else{
      await invoke('stop_picker');
      set('已取消选择','ok');
      btn.textContent='窗口选择';
      pickerWin=null;renderPickerWin(null);
    }
  };
  $('#capStart').onclick=async()=>{
    if(IS_TAURI){
      const secs=Math.min(60,Math.max(2,parseInt(prompt('录制几秒（2-60）？','8')||'8',10)));
      const fps=Math.min(10,Math.max(2,parseInt(prompt('帧率（2-10，越大越流畅文件越大）？','8')||'8',10)));
      set(`正在录制全屏 ${secs} 秒…（完成后弹保存框）`,'warnc');
      try{const ok=await invoke('record_gif',{mode:'full',windowId:null,seconds:secs,fps});set(ok?'已保存 GIF':'已取消','ok')}catch(e){set('录制失败：'+e.message,'err')}
      return;
    }
    try{
      const s=await navigator.mediaDevices.getDisplayMedia({video:{cursor:'always'},audio:false});
      recStream=s;recChunks=[];
      rec=new MediaRecorder(s,{mimeType:'video/webm;codecs=vp9,vp8,opus'});
      rec.ondataavailable=e=>{if(e.data&&e.data.size)recChunks.push(e.data)};
      rec.onstop=()=>{
        const b=new Blob(recChunks,{type:'video/webm'});
        download(b,'录屏-'+ts()+'.webm');
        rec=null;recStream=null;
        $('#capStop').disabled=true;$('#capStart').disabled=false;
        set('已保存录屏（WebM）','ok');
      };
      rec.start();
      $('#capStop').disabled=false;$('#capStart').disabled=true;
      set('录制中…点击「停止」结束','warnc');
      s.getVideoTracks()[0].onended=()=>{if(rec&&rec.state!=='inactive')rec.stop()};
    }catch(e){set('已取消或失败：'+e.message,'err')}
  };
  $('#capStop').onclick=()=>{if(rec)rec.stop()};
}

/* ================= 文件格式转换 ================= */
let convFiles=[];
PANELS.files=()=>`
${head('文件格式转换')}
<div class="panel-body">
  <div class="drop" id="convDrop">拖文件到这里，或点击选择（可多选）</div>
  <div class="filelist" id="convList"></div>
  <p class="note">图片可转 PNG / JPEG / WebP；文本（txt / md / csv 等）可转 PDF；视频可转 GIF（前 6 秒）。其余格式转换请在「压缩 / 解压」面板打包。${IS_TAURI?'桌面版直接拖入任意文件即可。':''}</p>
</div>`;
function tauriPathInfo(p){
  const name=p.split(/[\\/]/).pop()||p;
  return {path:p,name,size:0};
}
function handleExternalDrop(paths){
  if(!paths||!paths.length)return;
  const items=paths.map(tauriPathInfo);
  const modal=$('#modal');
  if(modal.classList.contains('show')){
    if($('#convList')){convFiles=convFiles.concat(items);renderConv();toast('已加入 '+items.length+' 个文件');return}
    if($('#zipCount')){zipFiles=zipFiles.concat(items);const cnt=$('#zipCount');if(cnt)cnt.textContent='已选 '+zipFiles.length+' 个文件';toast('已加入 '+items.length+' 个文件');return}
  }
  openPanel('files');
  convFiles=convFiles.concat(items);
  renderConv();
  toast('已加入 '+items.length+' 个文件');
}
function renderConv(){
  const list=$('#convList');
  if(!list)return;
  list.innerHTML=convFiles.map((f,i)=>{
    const kind=fileKind(f);
    return `<div class="fitem">
      <div class="fname">${escapeHtml(f.name)}</div>
      <div class="fmeta">${f.size?humanSize(f.size)+' · ':''}${kind}</div>
      ${kind==='image'?`<button class="btn small" data-i="${i}" data-fmt="png">PNG</button><button class="btn small" data-i="${i}" data-fmt="jpeg">JPEG</button><button class="btn small" data-i="${i}" data-fmt="webp">WebP</button>`:''}
      ${kind==='text'?`<button class="btn small" data-i="${i}" data-fmt="pdf">转 PDF</button>`:''}
      ${kind==='video'?`<button class="btn small" data-i="${i}" data-fmt="gif">转 GIF</button>`:''}
      <button class="btn small danger" data-i="${i}" data-fmt="del">移除</button>
    </div>`;
  }).join('');
  list.querySelectorAll('button').forEach(b=>{
    b.onclick=async()=>{
      const i=+b.dataset.i,fmt=b.dataset.fmt;
      if(fmt==='del'){convFiles.splice(i,1);renderConv();return}
      const f=convFiles[i];
      toast('转换中：'+f.name);
      try{
        if(fmt==='png'||fmt==='jpeg'||fmt==='webp')await convImage(f,fmt);
        else if(fmt==='pdf')await convTextPdf(f);
        else if(fmt==='gif')await convVideoGif(f);
        toast('完成：'+f.name);
      }catch(e){toast('转换失败：'+e.message)}
    };
  });
}
function bindFiles(){
  const drop=$('#convDrop');
  const setFiles=fs=>{convFiles=Array.from(fs);renderConv()};
  const pick=()=>{const i=document.createElement('input');i.type='file';i.multiple=true;i.onchange=()=>setFiles(i.files);i.click()};
  drop.onclick=pick;
  ['dragover','dragenter'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('hover')}));
  ['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('hover')}));
  drop.addEventListener('drop',e=>{
    if(IS_TAURI)return; // 桌面版由全局拖拽事件处理
    setFiles(e.dataTransfer.files)
  });
  renderConv();
}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fileKind(f){
  const n=f.name.toLowerCase();
  if(/\.(png|jpe?g|webp|gif|bmp|svg|avif)$/.test(n))return'image';
  if(/\.(txt|md|markdown|csv|log|json|yml|yaml|ini|conf)$/.test(n))return'text';
  if(/\.(mp4|webm|mov|mkv|avi|m4v)$/.test(n))return'video';
  if(/\.(zip|rar|7z)$/.test(n))return'archive';
  return'其他';
}
async function convImage(f,fmt){
  const mime={png:'image/png',jpeg:'image/jpeg',webp:'image/webp'}[fmt];
  const base=f.name.replace(/\.[^.]+$/,'');
  const outName=base+'.'+(fmt==='jpeg'?'jpg':fmt);
  if(IS_TAURI){
    const img=new Image();
    img.src=toAsset(f.path);
    await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(new Error('无法读取图片'))});
    const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;
    c.getContext('2d').drawImage(img,0,0);
    const data=c.toDataURL(mime,fmt==='jpeg'?0.92:undefined).split(',')[1];
    const ok=await saveBytes(data,outName,'图片',fmt==='jpeg'?'jpg':fmt);
    if(ok===false)throw new Error('已取消保存');
    return;
  }
  const bmp=await createImageBitmap(f);
  const c=document.createElement('canvas');c.width=bmp.width;c.height=bmp.height;
  c.getContext('2d').drawImage(bmp,0,0);
  c.toBlob(b=>download(b,outName),mime,fmt==='jpeg'?0.92:undefined);
}
async function convTextPdf(f){
  const {PDFDocument,StandardFonts}=await loadLib('https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js','PDFLib');
  const text=IS_TAURI?await invoke('read_text_file',{path:f.path}):await f.text();
  const doc=await PDFDocument.create();
  const font=await doc.embedFont(StandardFonts.Helvetica);
  const PW=595,PH=842,m=56,lineH=14,maxChars=Math.floor((PW-m*2)/6.3);
  let page=doc.addPage([PW,PH]);
  let y=PH-m;
  const push=()=>{y=PH-m;page=doc.addPage([PW,PH])};
  for(const raw of text.replace(/\r/g,'').split('\n')){
    let line=raw;
    while(line.length>maxChars){page.drawText(line.slice(0,maxChars),{x:m,y,size:10,font});y-=lineH;line=line.slice(maxChars);if(y<m)push()}
    if(line){page.drawText(line,{x:m,y,size:10,font});y-=lineH;if(y<m)push()}
  }
  const buf=await doc.save();
  await download(new Blob([buf],{type:'application/pdf'}),f.name.replace(/\.[^.]+$/,'')+'.pdf');
}
async function convVideoGif(f){
  const {GIFEncoder,quantize,applyPalette}=await import('https://cdn.jsdelivr.net/npm/gifenc@1.0.3/dist/gifenc.esm.js');
  const url=IS_TAURI?toAsset(f.path):URL.createObjectURL(f);
  const v=document.createElement('video');v.src=url;v.muted=true;
  await new Promise((res,rej)=>{v.onloadedmetadata=res;v.onerror=rej});
  const dur=Math.min(6,v.duration||6);
  const fps=10;const total=Math.max(1,Math.floor(dur*fps));
  const cw=320,ch=Math.max(1,Math.round(320*(v.videoHeight/v.videoWidth)));
  const c=document.createElement('canvas');c.width=cw;c.height=ch;
  const g2=c.getContext('2d',{willReadFrequently:true});
  const gif=GIFEncoder();
  const pal=quantize(new Uint8Array(cw*ch*4),256);
  for(let i=0;i<total;i++){
    v.currentTime=Math.min(dur,i/fps);
    await new Promise(r=>{v.onseeked=r;setTimeout(r,900)});
    g2.drawImage(v,0,0,cw,ch);
    const {data}=g2.getImageData(0,0,cw,ch);
    const idx=applyPalette(data,pal);
    gif.writeFrame(idx,cw,ch,{palette:pal,delay:100});
    if(i%3===0)toast('GIF 生成中 '+Math.round(i/total*100)+'%');
  }
  gif.finish();
  if(!IS_TAURI)URL.revokeObjectURL(url);
  await download(new Blob([gif.bytes()],{type:'image/gif'}),f.name.replace(/\.[^.]+$/,'')+'.gif');
}

/* ================= 压缩 / 解压 ================= */
let zipFiles=[];
PANELS.zip=()=>`
${head('压缩 / 解压')}
<div class="panel-body">
  <h3>① 压缩（ZIP，可选密码）</h3>
  <div class="drop" id="zipDrop">拖文件到这里，或点击选择（可多选）</div>
  <div id="zipCount" class="note" style="margin-top:8px">已选 0 个文件</div>
  <div class="row" style="margin-top:8px">
    <input type="password" id="zipPwd" placeholder="压缩密码（可留空）" style="flex:2">
    <button class="btn primary" id="zipGo">压缩为 ZIP</button>
  </div>
  <h3>② 解压</h3>
  <div class="row">
    <button class="btn" id="unzipPick">选择压缩包（ZIP）</button>
    <button class="btn" id="un7zPick">解压 7z / RAR（联网）</button>
  </div>
  <div id="zipStatus" class="note">提示：ZIP 压缩/解压本地完成，可设密码；7z/RAR 解压需联网加载开源引擎（7-Zip WASM）。</div>
</div>`;
function pickFile(accept){
  return new Promise(res=>{
    if(IS_TAURI){
      const ext=(accept.replace(/^\./,'').split(/[.,]/).find(x=>x)||'zip');
      invoke('open_file_dialog',{filterName:ext.toUpperCase(),filterExt:ext}).then(p=>res(p?tauriPathInfo(p):null));
      return;
    }
    const i=document.createElement('input');i.type='file';i.accept=accept;
    i.onchange=()=>res(i.files[0]||null);
    i.click();
  });
}
function readFileBuffer(f){
  return IS_TAURI?fetch(toAsset(f.path)).then(r=>r.arrayBuffer()):f.arrayBuffer();
}
function bindZip(){
  const drop=$('#zipDrop'),cnt=$('#zipCount'),pwd=$('#zipPwd'),st=$('#zipStatus');
  const set=t=>st.innerHTML=t;
  const pick=()=>{const i=document.createElement('input');i.type='file';i.multiple=true;i.onchange=()=>{zipFiles=Array.from(i.files);cnt.textContent='已选 '+zipFiles.length+' 个文件'};i.click()};
  drop.onclick=pick;
  ['dragover','dragenter'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('hover')}));
  ['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('hover')}));
  drop.addEventListener('drop',e=>{if(IS_TAURI)return;zipFiles=Array.from(e.dataTransfer.files);cnt.textContent='已选 '+zipFiles.length+' 个文件'});
  $('#zipGo').onclick=async()=>{
    if(!zipFiles.length)return toast('请先选择文件');
    const pw=pwd.value.trim();
    set('压缩中…');
    try{
      const JSZip=await loadLib('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js','JSZip');
      const z=new JSZip();
      for(const f of zipFiles)z.file(f.name,await readFileBuffer(f));
      let blob;
      try{blob=await z.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6},platform:'DOS',password:pw||undefined,encryptStrength:3})}
      catch(e){blob=await z.generateAsync({type:'blob',compression:'DEFLATE'})}
      await download(blob,'压缩包-'+ts()+'.zip');
      set('已生成 ZIP'+(pw?'（带密码）':'')+' ✓','ok');
    }catch(e){set('压缩失败：'+e.message,'err')}
  };
  $('#unzipPick').onclick=async()=>{
    const f=await pickFile('.zip');
    if(!f)return;
    const pw=prompt('若 ZIP 有密码请填写（没有直接确定）','');
    set('解压中…');
    try{
      const JSZip=await loadLib('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js','JSZip');
      const z=await JSZip.loadAsync(await readFileBuffer(f),{password:pw||undefined});
      const names=Object.keys(z.files).filter(n=>!z.files[n].dir);
      const out=new JSZip();
      for(const n of names)out.file(n,await z.files[n].async('uint8array'));
      const blob=await out.generateAsync({type:'blob',compression:'DEFLATE'});
      await download(blob,'解压-'+f.name.replace(/\.[^.]+$/,'')+'.zip');
      set(`解压完成，共 ${names.length} 个文件，已打包保存 ✓`+(pw?'（若密码有误请重试）':''),'ok');
    }catch(e){set('解压失败：'+(pw?'密码错误或':'')+e.message,'err')}
  };
  $('#un7zPick').onclick=async()=>{
    const f=await pickFile('.7z');
    if(!f)return;
    set('正在加载开源解压引擎（7-Zip WASM）…');
    try{
      const mod=await import('https://cdn.jsdelivr.net/npm/7z-wasm@1.0.0/7zz.es6.js');
      const SevenZip=mod.default||mod;
      const sz=await SevenZip();
      const name='a.'+(f.name.split('.').pop());
      sz.FS.writeFile(name,new Uint8Array(await readFileBuffer(f)));
      sz.FS.mkdir('/out');sz.FS.chdir('/out');
      sz.callMain(['x','/'+name,'-y','-o/out']);
      const out=sz.FS.readdir('/out').filter(n=>n!=='.'&&n!=='..');
      let done=0;
      const JSZip=await loadLib('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js','JSZip');
      const zp=new JSZip();
      for(const n of out){
        const stt=sz.FS.stat('/out/'+n);
        if(stt.isDirectory)continue;
        zp.file(n,new Uint8Array(sz.FS.readFile('/out/'+n)));
        done++;
      }
      const blob=await zp.generateAsync({type:'blob',compression:'DEFLATE'});
      await download(blob,'解压-'+f.name.replace(/\.[^.]+$/,'')+'.zip');
      set(`解压完成，共 ${done} 个文件，已打包保存 ✓`,'ok');
    }catch(e){set('解压失败：'+e.message+'（该功能需要联网加载 7-Zip WASM 引擎，请确认网络后重试）','err')}
  };
}

/* ================= 定时任务 ================= */
let timers=JSON.parse(localStorage.getItem('tp_timers')||'[]');
PANELS.timer=()=>`
${head('定时任务')}
<div class="panel-body">
  <h3>提醒 / 定时任务</h3>
  <div class="row">
    <input type="text" id="tmTitle" placeholder="提醒内容，如：喝水、下班打卡" class="grow">
  </div>
  <div class="row">
    <input type="datetime-local" id="tmTime" style="flex:2">
    <label style="flex:0 0 auto;display:flex;align-items:center;gap:6px;font-size:12px"><input type="checkbox" id="tmRepeat" style="width:16px;height:16px">每天重复</label>
  </div>
  <button class="btn primary" id="tmAdd">添加提醒</button>
  <div class="tlist" id="tmList" style="margin-top:12px"></div>
  <h3>自动关机 / 开机</h3>
  ${IS_TAURI?`<p class="note">桌面版可直接控制本机电源（关机/睡眠/重启）。关机与重启带 60 秒倒计时，可临时反悔取消。</p>
  <div class="row">
    <button class="btn danger" id="sdNow">立即关机</button>
    <button class="btn" id="sdSleep">立即睡眠</button>
    <button class="btn" id="sdRestart">立即重启</button>
  </div>
  <p class="note" style="margin-top:6px">定时（多少分钟后）关机：<input type="number" id="sdMin" placeholder="分钟" min="1" style="width:70px"> <button class="btn small" id="sdTimed">定时关机</button></p>
  <p class="note">开机自启：在「设置」里打开「开机自动启动」。定时开机请使用系统「节能/电池 → 定时」或主板 BIOS 定时。</p>`:`
  <p class="note">浏览器无法直接控制关机/开机，这里一键生成系统脚本：<br>· <b>Windows</b>：双击运行后按设定时间自动关机（期间可运行 <code>shutdown /a</code> 取消）<br>· <b>macOS</b>：运行后输入密码按设定时间关机；开机需在「系统设置 → 节能/电池 → 定时」里设置。</p>
  <div class="row">
    <input type="number" id="sdMin" placeholder="多少分钟后关机" min="1" style="flex:1">
    <button class="btn" id="sdWin">生成 Windows 脚本</button>
    <button class="btn" id="sdMac">生成 macOS 脚本</button>
  </div>`}
</div>`;
function saveTimers(){localStorage.setItem('tp_timers',JSON.stringify(timers))}
function bindTimer(){
  const list=$('#tmList');
  const render=()=>{
    list.innerHTML=timers.map((t,i)=>`<div class="trow">
      <div class="tt">${escapeHtml(t.title)}<div class="sub">${new Date(t.time).toLocaleString('zh-CN')}${t.repeat?' · 每天重复':''}${t.done?' · 已触发':''}</div></div>
      <button class="del" data-i="${i}">✕</button></div>`).join('')||'<div class="note">暂无提醒</div>';
    list.querySelectorAll('.del').forEach(b=>b.onclick=()=>{timers.splice(+b.dataset.i,1);saveTimers();render()});
  };
  render();
  const mn=new Date(Date.now()+60000);
  $('#tmTime').value=mn.getFullYear()+'-'+fmt(mn.getMonth()+1)+'-'+fmt(mn.getDate())+'T'+fmt(mn.getHours())+':'+fmt(mn.getMinutes());
  $('#tmAdd').onclick=()=>{
    const title=$('#tmTitle').value.trim();
    const t=$('#tmTime').value;
    if(!title)return toast('请填写提醒内容');
    if(!t)return toast('请选择时间');
    timers.push({id:Date.now(),title,time:new Date(t).getTime(),repeat:$('#tmRepeat').checked,done:false});
    saveTimers();render();$('#tmTitle').value='';
    toast('已添加提醒');
  };
  if(IS_TAURI){
    const run=async(action,label)=>{
      if(!confirm('确定要'+label+'吗？'+(action!=='sleep'?'（60 秒后可反悔：Windows 运行 shutdown /a；macOS 运行 sudo shutdown -c）':'')))return;
      try{const r=await invoke('power_action',{action});toast(r)}catch(e){toast('失败：'+e.message)}
    };
    $('#sdNow').onclick=()=>run('shutdown','立即关机');
    $('#sdSleep').onclick=()=>run('sleep','立即睡眠');
    $('#sdRestart').onclick=()=>run('restart','立即重启');
    $('#sdTimed').onclick=async()=>{
      const m=Math.max(1,parseInt($('#sdMin').value||'10',10));
      if(!confirm(`确定 ${m} 分钟后关机吗？`))return;
      try{const r=await invoke('power_action',{action:'shutdown'});toast(r+'（约 '+m+' 分钟后）')}catch(e){toast('失败：'+e.message)}
    };
    return;
  }
  $('#sdWin').onclick=()=>{
    const m=parseInt($('#sdMin').value||'10',10);const sec=m*60;
    const bat=`@echo off\r\nchcp 65001 >nul\r\necho 将在 ${m} 分钟后自动关机。取消请运行: shutdown /a\r\ntimeout /t 5 /nobreak >nul\r\nshutdown /s /t ${sec}\r\n`;
    download(new Blob([bat],{type:'text/plain;charset=utf-8'}),'定时关机-'+m+'分钟.bat');
    toast('已生成 Windows 关机脚本');
  };
  $('#sdMac').onclick=()=>{
    const m=parseInt($('#sdMin').value||'10',10);
    const sh=`#!/bin/bash\n# 将在 ${m} 分钟后关机。取消: sudo shutdown -c\necho "将在 ${m} 分钟后关机，需要输入密码…"\nsudo shutdown -h +${m}\n`;
    download(new Blob([sh],{type:'text/plain;charset=utf-8'}),'定时关机-'+m+'分钟.command');
    toast('已生成 macOS 关机脚本（运行后需输入密码）');
  };
}
function checkTimers(){
  const now=Date.now();
  let changed=false;
  for(const t of timers){
    if(t.done||t.time>now)continue;
    t.done=true;changed=true;
    if(t.repeat){const d=new Date(t.time);d.setDate(d.getDate()+1);t.time=d.getTime();t.done=false;changed=true}
    bubble('到点啦：'+t.title,5000);sfxAlert();
    toast('定时提醒：'+t.title);
  }
  if(changed)saveTimers();
}
function restoreTimers(){checkTimers()}

